function encodeSelection(entry,names){
 const prefixes=[], encoded=names.slice(), remaining=new Set(names.map((_,i)=>i));
 for(;;){
  const candidates=new Map();
  for(const i of remaining){
   const name=names[i];
   for(let j=0;j<name.length-1;j++)if(name[j]===' '&&j>=9){
    const prefix=name.slice(0,j+1);
    if(!candidates.has(prefix))candidates.set(prefix,[]);
    candidates.get(prefix).push(i);
   }
  }
  let best=null;
  for(const [prefix,indices] of candidates){
   if(indices.length<2)continue;
   const index=prefixes.length;
   const before=indices.reduce((n,i)=>n+JSON.stringify(names[i]).length,0);
   const after=JSON.stringify(prefix).length+1+indices.reduce((n,i)=>n+JSON.stringify([index,names[i].slice(prefix.length)]).length,0);
   const gain=before-after;
   if(gain>0&&(!best||gain>best.gain||(gain===best.gain&&prefix<best.prefix)))best={prefix,indices,gain};
  }
  if(!best)break;
  const index=prefixes.length;prefixes.push(best.prefix);
  for(const i of best.indices){encoded[i]=[index,names[i].slice(best.prefix.length)];remaining.delete(i);}
 }
 const block='const namePrefixes = '+JSON.stringify(prefixes)+';\nconst selections = {'+JSON.stringify(entry)+': '+JSON.stringify(encoded)+'.map(item => typeof item === "string" ? item : namePrefixes[item[0]] + item[1])};';
 return {block,prefixes,encoded};
}
